const $=id=>document.getElementById(id);let objects=SortingEngine.initial(),busy=false,logs=[],grip={x:400,y:70},held=null;
const colors={red:'#df7768',blue:'#6399c7',green:'#73a98a'};
function draw(){
 $('scene').innerHTML='<defs><pattern id="grid" width="25" height="25" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r="1" fill="#d5dfd4"/></pattern></defs><rect width="800" height="490" fill="url(#grid)"/>'+['left','right'].map((t,i)=>'<rect x="'+(i?640:40)+'" y="130" width="120" height="300" rx="16" fill="#eaf0e4" stroke="#b7c8ad" stroke-dasharray="5 5"/><text x="'+(i?700:100)+'" y="112" text-anchor="middle" fill="#759066" font-size="12" font-family="sans-serif">'+t.toUpperCase()+' TRAY</text>').join('')+'<text x="400" y="462" text-anchor="middle" fill="#9aab9b" font-size="10" letter-spacing="2">VIRTUAL TABLETOP • TOP VIEW</text>'+objects.map(o=>{let x=o.id===held?grip.x:o.x,y=o.id===held?grip.y:o.y;return '<g transform="translate('+x+' '+y+')">'+(o.shape==='circle'?'<circle r="'+o.width/2+'"':'<rect x="'+(-o.width/2)+'" y="'+(-o.width/2)+'" width="'+o.width+'" height="'+o.width+'" rx="5"')+' fill="'+colors[o.color]+'" stroke="#ffffff" stroke-width="2"/><text y="'+(o.width/2+16)+'" text-anchor="middle" fill="#53695c" font-size="11">'+o.id+'</text></g>'}).join('')+'<g transform="translate('+grip.x+' '+grip.y+')" fill="none" stroke="#294c3e" stroke-width="5" stroke-linejoin="round"><path d="M-25 13 V-16 H25 V13 M-25 13 H-16 M25 13 H16"/><circle cy="-23" r="5" fill="#294c3e"/></g>';
 $('inventory').innerHTML=objects.map(o=>'<span class="chip">'+o.id+' · '+o.size+' '+o.color+' '+o.shape+' · '+(o.tray||'table')+'</span>').join('');
}
function lock(v){busy=v;['run','reset',...[]].forEach(id=>$(id).disabled=v);document.querySelectorAll('.examples button').forEach(b=>b.disabled=v)}
function travel(x,y){return new Promise(resolve=>{const from={...grip},start=performance.now();function tick(now){const p=Math.min(1,(now-start)/650),e=p*p*(3-2*p);grip={x:from.x+(x-from.x)*e,y:from.y+(y-from.y)*e};draw();if(p<1)requestAnimationFrame(tick);else resolve()}requestAnimationFrame(tick)})}
function record(command,ok,message,ms){logs.push({command,result:ok?'completed':'rejected',message,duration_ms:Math.round(ms)});$('attempts').textContent=logs.length;$('success').textContent=logs.filter(x=>x.result==='completed').length;$('rejected').textContent=logs.filter(x=>x.result==='rejected').length;$('history').replaceChildren(...logs.slice().reverse().map(l=>{let li=document.createElement('li');li.textContent=(l.result==='completed'?'✓ ':'↳ ')+l.command+' — '+l.message;return li}))}
$('form').onsubmit=async e=>{e.preventDefault();if(busy)return;const command=$('command').value.trim(),start=performance.now(),p=SortingEngine.plan(command,objects);$('feedback').className=p.ok?'':'error';$('steps').replaceChildren();if(!p.ok){$('feedback').textContent=p.message;record(command,false,p.message,performance.now()-start);return}lock(true);$('state').textContent='Executing plan';$('feedback').textContent='Selected '+p.id+' → '+p.tray+' tray. Capacity check passed.';const o=objects.find(x=>x.id===p.id);function step(i){let li=document.createElement('li');li.textContent=p.steps[i];$('steps').append(li)}step(0);step(1);step(2);step(3);await travel(o.x,o.y);held=o.id;step(4);await travel(p.target.x,p.target.y);o.x=p.target.x;o.y=p.target.y;o.tray=p.tray;held=null;step(5);await travel(400,70);$('feedback').textContent='Success: '+p.id+' placed in the '+p.tray+' tray.';record(command,true,'Placed '+p.id+' in '+p.tray+' tray',performance.now()-start);$('state').textContent='Ready to sort';lock(false)};
document.querySelectorAll('.examples button').forEach(b=>b.onclick=()=>{$('command').value=b.textContent;$('command').focus()});
$('reset').onclick=()=>{if(busy)return;objects=SortingEngine.initial();grip={x:400,y:70};held=null;$('feedback').textContent='Scene reset. Session results retained.';$('feedback').className='';$('steps').replaceChildren();draw()};
$('export').onclick=()=>{const esc=s=>'"'+String(s).replace(/"/g,'""')+'"';let csv='command,result,message,duration_ms\r\n'+logs.map(l=>Object.values(l).map(esc).join(',')).join('\r\n');const a=document.createElement('a'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.href=url;a.download='sorting-results.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};draw();
